  world.add(weapon, ItemInfo, {
    type: "weapon",
    sockets: ["gem_fluorite"],
    maxSockets: 1,
  });
  return weapon;
}

function fluoriteSocket(world, weapon) {
  for (const [nodeId, socket] of childrenWith(world, weapon, GemSocketNode)) {
    if (socket.gemId === "gem_fluorite") return nodeId;
  }
  return 0;
}

