// src/rules/systems/aiFarmAnimalSystem.js
// Simple wandering AI for passive farm animals on the overworld (depth 0).
// Animals randomly scurry with a high rest chance, staying near their spawn.

import { Faction } from "../components/Faction.js";
import { CreatureType, CREATURE_TYPES } from "../components/CreatureType.js";
import { MoveIntent } from "../components/Intents/MoveIntent.js";
import { DungeonState } from "../components/DungeonState.js";
import { NamedIdentity } from "../components/NamedIdentity.js";
import { canActThisTurn } from "../utils/speedGate.js";
import { CARDINAL_DIRS } from "../utils/directions.js";
import { isWalkable } from "../environment/dungeon/tileMap.js";
import { playerEntity } from "../utils/queries.js";
import { forEachInRadius } from "../utils/spatialIndex.js";
import { getMonster } from "../data/monsters.js";
import { resolveSleepScheduleNow } from "../data/sleepProfiles.js";
import { isAsleep } from "../utils/sleep.js";

const ACTIVE_RADIUS = 8;
const VOCALIZATION_COOLDOWN = 200; // turns between vocalizations per chicken

/** Track vocalization cooldown per entity (Map<id, turnsLeft>) */
const _vocalizationCooldowns = new Map();

/** @param {import('../../lib/ecs-js/index.js').World} world */
export function aiFarmAnimalSystem(world) {
  // Only run on the overworld.
  let depth = -1;
  for (const [, ds] of world.query(DungeonState)) {
    depth = ds.currentDepth ?? -1;
    break;
  }
  if (depth !== 0) return;

  const player = playerEntity(world);
  if (!player) return;
  const pp = player.pos;

  forEachInRadius(world, pp.x, pp.y, ACTIVE_RADIUS, (id, pos) => {
    const fac = world.get(id, Faction);
    if (!fac || fac.key !== "neutral") return;

    const ct = world.get(id, CreatureType);
    if (!ct || ct.type !== CREATURE_TYPES.beast) return;

    const identity = String(world.get(id, NamedIdentity)?.identity || "");
    const def = getMonster(identity);
    if (def?._contentAiHints?.farmAnimal !== true) return;
    if (resolveSleepScheduleNow(def.sleep, world.step || 0) === true) return;
    if (isAsleep(world, id)) return;

    if (!canActThisTurn(world, id)) return;
    if (world.has(id, MoveIntent)) return;

    // Decrement vocalization cooldown
    const cooldown = _vocalizationCooldowns.get(id) ?? 0;
    if (cooldown > 0) {
      _vocalizationCooldowns.set(id, cooldown - 1);
    }

    // 5% chance to vocalize (if not on cooldown) — chickens cluck/cheep occasionally
    if (cooldown === 0 && world.rand() < 0.05) {
      if (identity) {
        world.emit?.('creature:vocalize', {
          id,
          identity,
          at: { x: pos.x | 0, y: pos.y | 0 },
        });
        _vocalizationCooldowns.set(id, VOCALIZATION_COOLDOWN);
      }
    }

    // 70% chance to rest — chickens mostly peck in place.
    if (world.rand() < 0.7) return;

    const dir = CARDINAL_DIRS[Math.floor(world.rand() * CARDINAL_DIRS.length)];
    const nx = (pos.x | 0) + dir.dx;
    const ny = (pos.y | 0) + dir.dy;
    if (!isWalkable(nx, ny)) return;

    try { world.add(id, MoveIntent, { dx: dir.dx, dy: dir.dy }); } catch {}
  });
}
import { AggroState, AGGRO_LEVELS } from "../components/AggroState.js";
import { AttackIntent } from "../components/Intents/AttackIntent.js";
import { MoveIntent } from "../components/Intents/MoveIntent.js";
import { Faction } from "../components/Faction.js";
import { Position } from "../components/Position.js";
import { Vitality } from "../components/Vitality.js";
import { findNextCardinalStep } from "../utils/gridPathfind.js";
import { playerEntity } from "../utils/queries.js";
import { statusStrength } from "../utils/statusFacade.js";

const SOCIAL_AGGRO_FACTIONS = new Set(["shopkeeper", "townfolk", "neutral"]);

function isSocialFaction(value) {
  return SOCIAL_AGGRO_FACTIONS.has(String(value || "").trim().toLowerCase());
}

function cardinalDistance(a, b) {
  return Math.abs((a.x | 0) - (b.x | 0)) + Math.abs((a.y | 0) - (b.y | 0));
}

function directCardinalStep(from, to) {
  const dx = (to.x | 0) - (from.x | 0);
  const dy = (to.y | 0) - (from.y | 0);
  if (Math.abs(dx) >= Math.abs(dy) && dx !== 0) return { dx: Math.sign(dx), dy: 0 };
  if (dy !== 0) return { dx: 0, dy: Math.sign(dy) };
  return null;
}

export function socialAggroSystem(world) {
  const player = playerEntity(world);
  if (!player) return;
  const playerId = player.id | 0;
  const playerPos = player.pos;
  if (!playerPos) return;

  const playerInvisible = statusStrength(world, playerId, "invisible") > 0;

  for (const [id, pos, faction, aggro] of world.query(Position, Faction, AggroState)) {
    if (id === playerId) continue;
    if (!isSocialFaction(faction?.key)) continue;
    if (aggro.alertLevel !== AGGRO_LEVELS.hunting) continue;

    const vit = world.get(id, Vitality);
    if (vit && (vit.hp | 0) <= 0) continue;

    const dist = cardinalDistance(pos, playerPos);
    if (playerInvisible && dist > 1) continue;

    try { world.remove(id, MoveIntent); } catch {}

    if (dist === 1) {
      try { world.add(id, AttackIntent, { targetId: playerId, allowNonHostile: true }); } catch {}
      continue;
    }

    const step = findNextCardinalStep(
      world,
      pos.x | 0,
      pos.y | 0,
      playerPos.x | 0,
      playerPos.y | 0,
      id,
      {
        goalRadius: 1,
        maxNodes: 128,
        searchPadding: 12,
        passThroughDoors: true,
      },
    ) || directCardinalStep(pos, playerPos);
    if (!step) continue;
    try { world.add(id, MoveIntent, { dx: step.dx | 0, dy: step.dy | 0 }); } catch {}
  }
}

