  return {
    learnedSpellIds: Array.isArray(input.learnedSpellIds) ? [...input.learnedSpellIds] : [],
    itemKnowledgeIdentities: Array.isArray(input.itemKnowledgeIdentities) ? [...input.itemKnowledgeIdentities] : [],
