function collectDropItemIds(world, actorId, monsterDef) {
  const out = [];
  const seen = new Set();
  const push = (itemId) => {
    const id = Number(itemId || 0) | 0;
    if (!(id > 0) || !world.isAlive(id)) return;
    if (seen.has(id)) return;
    if (!world.has(id, ItemInfo)) return;
    seen.add(id);
    out.push(id);
