  applyMutation(world, {
    type: "spawnMonster",
    monsterId: id,
    x: spawnAt.x,
    y: spawnAt.y,
    emitEvent: true,
  }, { getMonster });

  return {
    ok: true,
    monsterId: id,
    name: String(def.name || id),
    x: spawnAt.x,
    y: spawnAt.y,
