    name: p.name,
    identity: p.identity,
    maxHp: Number.isFinite(p.maxHp) ? (Number(p.maxHp) | 0) : undefined,
    hp: Number.isFinite(p.hp) ? (Number(p.hp) | 0) : undefined,
    faction: p.faction,

