  const enemy = world.create();
  world.add(enemy, Vitality, { hp: 10, maxHp: 10 });
  world.add(enemy, ActiveEffects, {
    effects: [{ key: 'stasis', turnsLeft: 8, stacks: 1, potency: 1 }],
  });

  assertEquals(statusStrength(world, enemy, 'stasis'), 0);
});

