  const query = {
    get(id, Comp) { return world.get(id, Comp) || null; },
    name(id) { return String(world.get(id, NamedIdentity)?.name || ''); },
    identity(id) { return String(world.get(id, NamedIdentity)?.identity || ''); },
  };

  const helpers = {
    heal(entityId, amount) {
