    consume() {},
    spawnItem() { return null; },
    spawnMonster() { return null; },
    hazardSpawn() {},
    emit(event, payload) { world.emit(event, payload); },
    message(text, type) { world.emit('log:message', { text, type: type || 'system' }); },
  };

