    actor,
    primary: itemId,
    target: 0,
    query,
    helpers,
    io: { emit: (e, p) => world.emit(e, p) },

    // ── Extended APIs for ScriptCtx ──────────────────────────────
    _ScriptState: ScriptState,
    _ItemInfo: ItemInfo,

    _hpPercent(entityId) {
