    _setCooldown(entityId, turns) {
      setItemCooldown(world, entityId, turns);
    },
    _isOnCooldown(entityId) {
      return isItemOnCooldown(world, entityId);
    },
    _cooldownRemaining(entityId) {
      return getItemCooldownRemaining(world, entityId);
    },
  };
}
