/**
 * Queue a CastSpellIntent for a monster while it has LOS to target.
 * Uses cooldown/chance/range gating and optional ally-count cap to avoid
 * runaway summon spam.
 *
 * @param {{
 *   spellId: string,
 *   abilityId?: string,
 *   abilityName?: string,
 *   targeting?: "enemy"|"self",
 *   minRange?: number,
 *   maxRange?: number,
 *   cooldownTurns?: number,
 *   chance?: number,
 *   consumeTurn?: boolean,
 *   telegraphTurns?: number,
 *   maxAlliesInRadius?: number,
 *   allyRadius?: number,
 * }} opts
 */
export function castSpellOnLOS(opts) {
  const spellId = String(opts?.spellId || "").trim();
  const abilityId = String(opts?.abilityId || spellId || "").trim();
  const abilityName = String(opts?.abilityName || abilityId || spellId || "").trim();
  const targeting = String(opts?.targeting || "enemy") === "self" ? "self" : "enemy";
  const minRange = Math.max(0, Number.isFinite(opts?.minRange) ? (Number(opts.minRange) | 0) : 0);
  const maxRangeOpt = Number.isFinite(opts?.maxRange) ? (Number(opts.maxRange) | 0) : -1;
  const cooldownTurns = Math.max(0, Number.isFinite(opts?.cooldownTurns) ? (Number(opts.cooldownTurns) | 0) : 8);
  const chance = Number.isFinite(opts?.chance) ? Math.max(0, Math.min(1, Number(opts.chance))) : 1;
  const consumeTurn = opts?.consumeTurn !== false;
  const telegraphTurns = Math.max(0, Number.isFinite(opts?.telegraphTurns) ? (Number(opts.telegraphTurns) | 0) : 0);
  const maxAlliesInRadius = Number.isFinite(opts?.maxAlliesInRadius) ? (Number(opts.maxAlliesInRadius) | 0) : -1;
  const allyRadius = Math.max(1, Number.isFinite(opts?.allyRadius) ? (Number(opts.allyRadius) | 0) : 6);

  return (ctx) => {
    if (!ctx || ctx.cancelled) return;
    if (!spellId) return;
    if (!ctx.canActThisTurn || ctx.hasQueuedMove) return;
    const now = Number(ctx.world.step || 0) | 0;
    const windupStore = ensureAbilityWindupState(ctx.world);
    const windupKey = abilityWindupSlot(ctx.actor, abilityId);
    const pendingWindup = windupStore.get(windupKey) || null;
    const windupReady = !!(pendingWindup && now >= (Number(pendingWindup.readyStep || 0) | 0));

    if (!windupReady && !worldChance(ctx.world, chance)) return;
    if (ctx.world.has(ctx.actor, CastSpellIntent) || ctx.world.has(ctx.actor, Channeling)) return;

    const spell = getSpell(spellId);
    if (!spell) return;
    if (spellCastOnCooldown(ctx.world, ctx.actor, spellId, cooldownTurns)) return;

    const actorPos = ctx.actorPos;
    const targetPos = ctx.targetPos;
    const maxRange = maxRangeOpt >= 0
      ? Math.max(minRange, maxRangeOpt)
      : Math.max(minRange, Number(spell.range || 8) | 0);

    if (!windupReady && targeting !== "self") {
      if (!actorPos || !targetPos) return;
      const dist = chebyshev(actorPos, targetPos);
      if (dist < minRange || dist > maxRange) return;
    }

    if (maxAlliesInRadius >= 0) {
      const faction = String(ctx.world.get(ctx.actor, Faction)?.key || "").trim();
      if (faction && actorPos) {
        let allies = 0;
        for (const [_id, pos, fac, vit] of ctx.world.query(Position, Faction, Vitality)) {
          if (!pos || !fac || !vit || (vit.hp | 0) <= 0) continue;
          if (String(fac.key || "") !== faction) continue;
          if (chebyshev(actorPos, pos) > allyRadius) continue;
          allies++;
        }
        if (allies > maxAlliesInRadius) return;
      }
    }

    const resource = spellCostResource(spell);
    const need = Math.max(0, Number(spellCost(spell)));
    if (resource === "stamina") {
      const stamina = ctx.world.get(ctx.actor, Stamina);
      if (stamina) {
        const have = Number(stamina.stamina || 0);
        if (have < need) return;
      }
    } else if (resource === "life") {
      const vitality = ctx.world.get(ctx.actor, Vitality);
      if (vitality) {
        const have = Number(vitality.hp || 0);
        if (have - need < 1) return;
      }
    } else {
      const mana = ctx.world.get(ctx.actor, Mana);
      if (mana && Number(mana.mana || 0) < need) return;
    }

    if (telegraphTurns > 0 && !windupReady) {
      const readyStep = now + telegraphTurns;
      windupStore.set(windupKey, {
        readyStep,
        targetId: (ctx.target | 0) > 0 ? (ctx.target | 0) : 0,
        targetX: actorPos ? (targetPos?.x ?? actorPos.x) | 0 : 0,
        targetY: actorPos ? (targetPos?.y ?? actorPos.y) | 0 : 0,
      });
      ctx.emit("monster:ability:windup", {
        actor: ctx.actor,
        targetId: (ctx.target | 0) > 0 ? (ctx.target | 0) : 0,
        abilityId,
        abilityName,
        spellId,
        turns: telegraphTurns,
        at: actorPos ? { x: actorPos.x | 0, y: actorPos.y | 0 } : undefined,
      });
      if (consumeTurn) ctx.setHandled(true);
      return;
    }

    const castIntent = { spellId };
    if (targeting !== "self") {
      const pendingTargetId = Number(pendingWindup?.targetId || 0) | 0;
      const chosenTarget = pendingTargetId > 0 ? pendingTargetId : (ctx.target | 0);
      if (chosenTarget > 0) castIntent.targetId = chosenTarget;
      if (Number.isFinite(pendingWindup?.targetX) && Number.isFinite(pendingWindup?.targetY)) {
        castIntent.x = Number(pendingWindup.targetX) | 0;
        castIntent.y = Number(pendingWindup.targetY) | 0;
      }
    }

    try {
      ctx.world.add(ctx.actor, CastSpellIntent, castIntent);
    } catch {
      return;
    }

    markSpellCastUsed(ctx.world, ctx.actor, spellId, cooldownTurns);
    if (pendingWindup) windupStore.delete(windupKey);
    ctx.emit("monster:castSpellIntent", {
      actor: ctx.actor,
      spellId,
      targetId: Number(castIntent.targetId || 0) | 0,
    });
    ctx.emit("monster:ability:cast", {
      actor: ctx.actor,
      targetId: Number(castIntent.targetId || 0) | 0,
      abilityId,
      abilityName,
      spellId,
      telegraphed: !!pendingWindup,
    });
    if (consumeTurn) ctx.setHandled(true);
  };
}
// rules/interaction/dispatch.js
// Run an ordered list of callbacks, short-circuiting on cancellation.

/**
 * Execute callbacks in order. Stops immediately if ctx.cancelled becomes true.
 * @param {Array<(ctx: any) => void> | undefined | null} callbacks
 * @param {any} ctx — must expose a `cancelled` property
 * @returns {boolean} true if all callbacks ran without cancellation
 */
export function runCallbackList(callbacks, ctx) {
  if (!Array.isArray(callbacks)) return true;
  for (let i = 0; i < callbacks.length; i++) {
    if (ctx.cancelled) return false;
    const fn = callbacks[i];
    if (typeof fn === "function") fn(ctx);
  }
  return !ctx.cancelled;
}

/**
 * Witness-based aggro for hidden attacks:
 * enemies that have LOS to the attacker at the moment of stealth offense
 * enter hunting and track attacker last-known position.
 *
 * @param {import('../../lib/ecs-js/index.js').World} world
 */
export function installAggroFromStealthOffenseListener(world) {
  if (world[AGGRO_STEALTH_OFFENSE_INSTALLED]) return;
  world[AGGRO_STEALTH_OFFENSE_INSTALLED] = true;

  world.on("stealth:offense", ({ entityId, at }) => {
    const attackerId = Number(entityId || 0) | 0;
    if (!(attackerId > 0)) return;
    const attackerPos = at && Number.isFinite(at.x) && Number.isFinite(at.y)
      ? { x: at.x | 0, y: at.y | 0 }
      : world.get(attackerId, Position);
    if (!attackerPos) return;

    const isBlocked = blockedCallback(buildBlocksVisionMap(world));
    forEachInRadius(world, attackerPos.x, attackerPos.y, ACTIVE_RADIUS, (id, pos) => {
      if (id === attackerId) return;
      const fac = world.get(id, Faction);
      if (!fac || fac.key !== "enemy") return;
      const aggro = world.get(id, AggroState);
      if (!aggro) return;
      if (sleepPreventsPerception(world, id)) return;

      const sightRange = Math.max(0, Math.trunc(getEffectiveVisionRange(world, id)));
      if (chebyshevScalar(pos.x, pos.y, attackerPos.x, attackerPos.y) > sightRange) return;
      const canWitness = (
        hasOverworldAerialLOS(world, {
          sourceId: id,
          targetId: attackerId,
          sourcePos: pos,
          targetPos: attackerPos,
          range: sightRange,
        }) || hasLOS(
          pos.x | 0, pos.y | 0,
          attackerPos.x | 0, attackerPos.y | 0,
          isBlocked,
        )
      );
      if (!canWitness) return;

      aggro.alertLevel = AGGRO_LEVELS.hunting;
      aggro.lastKnownX = attackerPos.x | 0;
      aggro.lastKnownY = attackerPos.y | 0;
      aggro.searchTurnsLeft = SEARCH_TURNS_HUNTING_GRACE;
      world.emit?.("status", { id, kind: "alert", at: { x: pos.x | 0, y: pos.y | 0 } });
    });
  });
}

// ── AI chase system ───────────────────────────────────────────────────

/** @param {any} world */
export function aiChaseSystem(world) {
  // Locate the player.
  const _player = playerEntity(world);
  if (!_player) return;
  const playerId  = _player.id;
  const playerPos = _player.pos;

  // Lazily built blocking map for LOS checks (built once, shared this tick).
  let _isBlocked = null;
  const ensureBlockedMap = () => {
    if (!_isBlocked) _isBlocked = blockedCallback(buildBlocksVisionMap(world));
    return _isBlocked;
  };

  // Ring of Conflict: enemies target each other instead of the player.
  const conflictActive = playerHasConflict(world, playerId);

  forEachInRadius(world, playerPos.x, playerPos.y, ACTIVE_RADIUS, (id, pos) => {
    const ni = world.get(id, NamedIdentity);
    const def = ni ? getMonster(String(ni.identity || "")) : null;
    const fac = world.get(id, Faction);
    const canChase = !!fac && fac.key === "enemy";
    if (!canChase && !def?.alertOnSight) return;

    const aggro = world.get(id, AggroState);
    if (!aggro) return; // no AggroState = no AI behaviour
    if (sleepPreventsPerception(world, id)) return;

    // ── Look up monster def and brain-backed awareness ──────────────
    const brain = world.get(id, Brain);
    const intel = Number(brain?.intelligence ?? def?.intelligence ?? 10);

    const canActThisTurn = speedGateCheck(world, id);
    const hasQueuedAction = world.has(id, MoveIntent) || world.has(id, FlyIntent);

    // Perception is driven by Brain data rather than action cadence.
    // Use getEffectiveVisionRange so that stat envelope effects (e.g. blindness) apply.
    const sightRange = Math.max(0, Math.trunc(getEffectiveVisionRange(world, id)));
    const withinSightRange = chebyshevScalar(pos.x, pos.y, playerPos.x, playerPos.y) <= sightRange;
    const invisibleTarget = statusStrength(world, playerId, "invisible") > 0;
    const adjacentToTarget = chebyshevScalar(pos.x, pos.y, playerPos.x, playerPos.y) <= 1;
    const canSeeNormally = withinSightRange && (
      hasOverworldAerialLOS(world, {
        sourceId: id,
        targetId: playerId,
        sourcePos: pos,
        targetPos: playerPos,
        range: sightRange,
      }) || hasLOS(
        pos.x | 0, pos.y | 0,
        playerPos.x | 0, playerPos.y | 0,
        ensureBlockedMap(),
      )
    );
    // Stealth rule: non-adjacent invisible targets should not keep enemies in chase mode.
    // They fall back to unaware state so idle movement (scurry/patrol) takes over.
    if (invisibleTarget && !adjacentToTarget) {
      if (aggro.alertLevel !== AGGRO_LEVELS.unaware) {
        aggro.alertLevel = AGGRO_LEVELS.unaware;
        setAggroTarget(world, id, aggro, 0, "lost");
        aggro.searchTurnsLeft = 0;
        aggro.retreating = false;
      }
      return;
    }
    const canSee = canSeeNormally;

    // ── Alert level transitions ─────────────────────────────────────
    if (canSee) {
      if (!canChase) {
        emitSightAlert(world, id, pos, def, aggro);
        return;
      }

      // Passive creatures (e.g. bat, cave_snake, snake) don't aggro from sight
      // while unaware — they are only aggroed by taking damage.
      if (def?.aggro === "passive" && aggro.alertLevel === AGGRO_LEVELS.unaware) {
        if (def?.alertOnSight || Number(def?.sightAlertCooldownTurns || 0) > 0) {
          emitSightAlert(world, id, pos, def, aggro);
        }
        return;
      }

      // Safety in numbers: unaware pack creatures won't aggro from sight alone.
      // They need at least one same-species ally within packRadius.
      if (def?.packSense && aggro.alertLevel === AGGRO_LEVELS.unaware) {
        const myIdentity = ni?.identity;
        if (myIdentity) {
          const packRadius = Math.max(1, (def.packRadius ?? 8) | 0);
          let hasAlly = false;
          forEachInRadius(world, pos.x, pos.y, packRadius, (neighborId) => {
            if (hasAlly) return;
            if (neighborId === id) return;
            if (sleepPreventsPerception(world, neighborId)) return;
            const neighborNI = world.get(neighborId, NamedIdentity);
            if (neighborNI && neighborNI.identity === myIdentity) hasAlly = true;
          });
          if (!hasAlly) return;
        }
      }

      const wasHunting = aggro.alertLevel === AGGRO_LEVELS.hunting;

      aggro.alertLevel      = AGGRO_LEVELS.hunting;
      aggro.lastKnownX      = playerPos.x | 0;
      aggro.lastKnownY      = playerPos.y | 0;
      aggro.searchTurnsLeft = SEARCH_TURNS_HUNTING_GRACE;

      // Track player movement direction for intel ≥ 8 anticipation on LOS break.
      const playerFacing = world.get(playerId, Facing);
      if (playerFacing) {
        const fdx = playerFacing.dx | 0;
        const fdy = playerFacing.dy | 0;
        if (fdx !== 0 || fdy !== 0) {
          aggro.lastKnownMoveDx = fdx;
          aggro.lastKnownMoveDy = fdy;
        }
      }

      // ── First sighting: onSeen hooks + pack alerting ────────────
      if (!wasHunting) {
        emitSightAlert(world, id, pos, def, aggro);
