        for (let ei = 0; ei < ae.effects.length; ei++) {
            const ex = ae.effects[ei];
            if (!ex) continue;
            const tl = Number.isInteger(ex.turnsLeft) ? ex.turnsLeft : 0;
            if (tl > 0) continue;
            if (Number.isInteger(ex.onsetLeft) && ex.onsetLeft > 0) continue;
