      if (cursedCount > 0) {
        statusStrengths.set('cursed', (statusStrengths.get('cursed') || 0) + cursedCount);
      }
    }
  }

  const sleep = world.get(id, SleepState);
  if (sleep?.asleep === true) {
    statusStrengths.set("sleep", Math.max(1, Number(statusStrengths.get("sleep") || 0)));
