/**
 * Gaze aura: starts a channeled gaze_beam spell when the eye has LOS.
 * The channeling system handles countdown, interruption (stun/silence/LOS break),
 * and fires the gaze_beam script on completion (stun + mindwipe).
 * Each turn in LOS emits escalating `proc:gaze:message` and `proc:gaze:charging`
 * events for UI wiring.
 *
 * @param {number} [exposureTurns=8] - channel duration (turns before gaze fires)
 */
export function gazeOnLOS(exposureTurns = 8) {
  const castTime = Math.max(1, Math.trunc(exposureTurns));

  const MESSAGES = [
    "The Floating Eye's unblinking gaze washes over you.",
    "Your thoughts feel sluggish under its stare...",
    "The eye's gaze presses deeper into your mind.",
    "Your concentration is slipping away...",
    "The Floating Eye's gaze sears into your mind!",
  ];

  return (ctx) => {
    if (!ctx || ctx.cancelled) return;
    if (!ctx.canActThisTurn) return;
    const world = ctx.world;
    const actor = ctx.actor | 0;
    const target = ctx.target | 0;
    const now = (Number(world.step) || 0) | 0;

    // If already channeling gaze_beam, emit progress events
    const ch = world.has(actor, Channeling) ? world.get(actor, Channeling) : null;
    if (ch && String(ch.spellId || '') === 'gaze_beam') {
      const elapsed = Math.max(0, (ch.turnsTotal | 0) - (ch.turnsRemaining | 0));
      const msgIdx = Math.min(elapsed, MESSAGES.length - 1);
      ctx.emit('proc:gaze:message', {
        actor, target, step: elapsed + 1, message: MESSAGES[msgIdx],
      });
      ctx.emit('proc:gaze:charging', {
        actor, target, chargeCount: elapsed + 1, total: ch.turnsTotal | 0, turn: now,
      });
      return;
    }

    // Don't start a new channel if already channeling something else
    if (ch) return;

    // Start gaze beam channel
    const actorPos = ctx.actorPos;
    try {
      world.add(actor, Channeling, {
        mode: 'cast',
        turnsRemaining: castTime,
        turnsTotal: castTime,
        manaPerTick: 0,
        spellId: 'gaze_beam',
        targetId: target,
        x: null,
        y: null,
        breakOnNoLos: true,
        breakOnMove: true,
        anchorX: actorPos ? (actorPos.x | 0) : null,
        anchorY: actorPos ? (actorPos.y | 0) : null,
      });
    } catch { return; }

    // First escalating message on channel start
    ctx.emit('proc:gaze:message', {
      actor, target, step: 1, message: MESSAGES[0],
    });
    ctx.emit('proc:gaze:charging', {
      actor, target, chargeCount: 1, total: castTime, turn: now,
    });
  };
}

/**
 * Queue a CastSpellIntent for a monster while it has LOS to target.
 * Uses cooldown/chance/range gating and optional ally-count cap to avoid
 * runaway summon spam.
 *
 * @param {{
 *   spellId: string,
 *   abilityId?: string,
 *   abilityName?: string,
 *   targeting?: "enemy"|"self",
 *   minRange?: number,
 *   maxRange?: number,
 *   cooldownTurns?: number,
 *   chance?: number,
 *   consumeTurn?: boolean,
 *   telegraphTurns?: number,
 *   maxAlliesInRadius?: number,
 *   allyRadius?: number,
 * }} opts
 */
export function castSpellOnLOS(opts) {
  const spellId = String(opts?.spellId || "").trim();
  const abilityId = String(opts?.abilityId || spellId || "").trim();
  const abilityName = String(opts?.abilityName || abilityId || spellId || "").trim();
  const targeting = String(opts?.targeting || "enemy") === "self" ? "self" : "enemy";
  const minRange = Math.max(0, Number.isFinite(opts?.minRange) ? (Number(opts.minRange) | 0) : 0);
  const maxRangeOpt = Number.isFinite(opts?.maxRange) ? (Number(opts.maxRange) | 0) : -1;
  const cooldownTurns = Math.max(0, Number.isFinite(opts?.cooldownTurns) ? (Number(opts.cooldownTurns) | 0) : 8);
  const chance = Number.isFinite(opts?.chance) ? Math.max(0, Math.min(1, Number(opts.chance))) : 1;
  const consumeTurn = opts?.consumeTurn !== false;
  const telegraphTurns = Math.max(0, Number.isFinite(opts?.telegraphTurns) ? (Number(opts.telegraphTurns) | 0) : 0);
  const maxAlliesInRadius = Number.isFinite(opts?.maxAlliesInRadius) ? (Number(opts.maxAlliesInRadius) | 0) : -1;
  const allyRadius = Math.max(1, Number.isFinite(opts?.allyRadius) ? (Number(opts.allyRadius) | 0) : 6);

  return (ctx) => {
    if (!ctx || ctx.cancelled) return;
    if (!spellId) return;
    if (!ctx.canActThisTurn || ctx.hasQueuedMove) return;
    const now = Number(ctx.world.step || 0) | 0;
    const windupStore = ensureAbilityWindupState(ctx.world);
    const windupKey = abilityWindupSlot(ctx.actor, abilityId);
    const pendingWindup = windupStore.get(windupKey) || null;
    const windupReady = !!(pendingWindup && now >= (Number(pendingWindup.readyStep || 0) | 0));

    if (!windupReady && !worldChance(ctx.world, chance)) return;
    if (ctx.world.has(ctx.actor, CastSpellIntent) || ctx.world.has(ctx.actor, Channeling)) return;

    const spell = getSpell(spellId);
    if (!spell) return;
    if (spellCastOnCooldown(ctx.world, ctx.actor, spellId, cooldownTurns)) return;

    const actorPos = ctx.actorPos;
    const targetPos = ctx.targetPos;
    const maxRange = maxRangeOpt >= 0
      ? Math.max(minRange, maxRangeOpt)
      : Math.max(minRange, Number(spell.range || 8) | 0);

    if (!windupReady && targeting !== "self") {
      if (!actorPos || !targetPos) return;
      const dist = chebyshev(actorPos, targetPos);
      if (dist < minRange || dist > maxRange) return;
    }

    if (maxAlliesInRadius >= 0) {
      const faction = String(ctx.world.get(ctx.actor, Faction)?.key || "").trim();
      if (faction && actorPos) {
        let allies = 0;
        for (const [_id, pos, fac, vit] of ctx.world.query(Position, Faction, Vitality)) {
          if (!pos || !fac || !vit || (vit.hp | 0) <= 0) continue;
          if (String(fac.key || "") !== faction) continue;
          if (chebyshev(actorPos, pos) > allyRadius) continue;
          allies++;
        }
        if (allies > maxAlliesInRadius) return;
      }
    }

    const resource = spellCostResource(spell);
    const need = Math.max(0, Number(spellCost(spell)));
    if (resource === "stamina") {
      const stamina = ctx.world.get(ctx.actor, Stamina);
      if (stamina) {
        const have = Number(stamina.stamina || 0);
        if (have < need) return;
      }
    } else if (resource === "life") {
      const vitality = ctx.world.get(ctx.actor, Vitality);
      if (vitality) {
        const have = Number(vitality.hp || 0);
        if (have - need < 1) return;
      }
    } else {
      const mana = ctx.world.get(ctx.actor, Mana);
      if (mana && Number(mana.mana || 0) < need) return;
    }

    if (telegraphTurns > 0 && !windupReady) {
      const readyStep = now + telegraphTurns;
      windupStore.set(windupKey, {
        readyStep,
        targetId: (ctx.target | 0) > 0 ? (ctx.target | 0) : 0,
        targetX: actorPos ? (targetPos?.x ?? actorPos.x) | 0 : 0,
        targetY: actorPos ? (targetPos?.y ?? actorPos.y) | 0 : 0,
      });
      ctx.emit("monster:ability:windup", {
        actor: ctx.actor,
        targetId: (ctx.target | 0) > 0 ? (ctx.target | 0) : 0,
        abilityId,
        abilityName,
        spellId,
        turns: telegraphTurns,
        at: actorPos ? { x: actorPos.x | 0, y: actorPos.y | 0 } : undefined,
      });
      if (consumeTurn) ctx.setHandled(true);
      return;
    }

    const castIntent = { spellId };
    if (targeting !== "self") {
      const pendingTargetId = Number(pendingWindup?.targetId || 0) | 0;
      const chosenTarget = pendingTargetId > 0 ? pendingTargetId : (ctx.target | 0);
      if (chosenTarget > 0) castIntent.targetId = chosenTarget;
      if (Number.isFinite(pendingWindup?.targetX) && Number.isFinite(pendingWindup?.targetY)) {
        castIntent.x = Number(pendingWindup.targetX) | 0;
        castIntent.y = Number(pendingWindup.targetY) | 0;
      }
    }

    try {
      ctx.world.add(ctx.actor, CastSpellIntent, castIntent);
    } catch {
      return;
    }

    markSpellCastUsed(ctx.world, ctx.actor, spellId, cooldownTurns);
    if (pendingWindup) windupStore.delete(windupKey);
    ctx.emit("monster:castSpellIntent", {
      actor: ctx.actor,
      spellId,
      targetId: Number(castIntent.targetId || 0) | 0,
    });
    ctx.emit("monster:ability:cast", {
      actor: ctx.actor,
      targetId: Number(castIntent.targetId || 0) | 0,
      abilityId,
      abilityName,
      spellId,
      telegraphed: !!pendingWindup,
    });
    if (consumeTurn) ctx.setHandled(true);
  };
}
// src/rules/systems/aiFlyingSystem.js
// Produces FlyIntent for monsters with canFly based on aggro/search state,
// adjacency, and floor eligibility. Takeoff / landing resolves later as a
// full action in flyIntentSystem so it consumes the turn.

import { AGGRO_LEVELS } from "../components/AggroState.js";
import { Position } from "../components/Position.js";
import { Speed } from "../components/Speed.js";
import { NamedIdentity } from "../components/NamedIdentity.js";
import { Flying } from "../components/Flying.js";
import { Vitality } from "../components/Vitality.js";
import { FlyIntent } from "../components/Intents/FlyIntent.js";
import { getMonster } from "../data/monsters.js";
import { canMonsterFlyOnFloor } from "../utils/flyingEligibility.js";
import { chebyshevScalar } from "../utils/distance.js";
import { playerEntity, queryAggroPositioned } from "../utils/queries.js";

/**
 * @param {import('../../lib/ecs-js/index.js').World} world
 */
export function aiFlyingSystem(world) {
  const _player = playerEntity(world);
  const hasPlayer = _player != null;
  const playerX = _player?.pos.x ?? 0;
  const playerY = _player?.pos.y ?? 0;

  for (const [id, aggro, pos] of queryAggroPositioned(world)) {
    const spd = world.get(id, Speed);
    const actEvery = (spd && spd.actEvery > 1) ? spd.actEvery : 1;
    if (actEvery > 1 && ((world.step + id) % actEvery) !== 0) continue;

    const ni = world.get(id, NamedIdentity);
    const identity = ni?.identity || "";
    const def = getMonster(identity);
    if (!def || !def.canFly) continue;
    const floorAllowsFlight = canMonsterFlyOnFloor(world, def);

    const isFlying = world.has(id, Flying);
    if (world.has(id, FlyIntent)) continue;

    const alert = aggro.alertLevel;
    const isAware = alert !== AGGRO_LEVELS.unaware;
    const sizeClass = String(def.sizeClass || "").toUpperCase();
    const prefersAirborneWhenDisturbed = sizeClass === "XS";
    const isAdjacent = hasPlayer && chebyshevScalar(pos.x, pos.y, playerX, playerY) <= 1;
    const vit = world.get(id, Vitality);
    const retreatThreshold = Number(def.retreatHpPct || 0);
    const hpFraction = vit ? (vit.hp / Math.max(1, vit.maxHp)) : 1;
    const escapeBiased = retreatThreshold > 0 && hpFraction < retreatThreshold && isAware;

    // Flyers stay airborne through alerted/curious search states so breaking
    // LOS creates a more committed escape profile instead of an instant landing.
    const shouldFly = floorAllowsFlight
      && isAware
      && (prefersAirborneWhenDisturbed || !isAdjacent)
      && (
        alert === AGGRO_LEVELS.hunting
        || alert === AGGRO_LEVELS.alerted
        || alert === AGGRO_LEVELS.curious
        || escapeBiased
      );

    if (shouldFly === isFlying) continue;
    try { world.add(id, FlyIntent, { airborne: shouldFly }); } catch {}
  }
}
// src/rules/systems/aiScurrySystem.js
// Idle movement for unaware enemies: low-intelligence creatures roam randomly,
// higher-intelligence creatures patrol in a persistent direction.
//
//   intelligence ≤ 3  → random scurry (rats, bats, snakes): random direction each
//                        turn with 50 % rest chance.
//   intelligence > 3  → directed patrol (goblins, skeletons, orcs…): maintains a
//                        patrol heading stored in AggroState.patrolDx/patrolDy.
//                        The heading persists until the monster hits a wall, then
//                        a new random direction is chosen.  Doors are NOT treated
//                        as walls here — the bump resolver handles opening them.
//
// Runs before aiChaseSystem in the 'ai' phase so the existing intent-skip guard
// (`if (world.has(id, MoveIntent)) return`) prevents aiChaseSystem from overriding.

import { Faction }     from "../components/Faction.js";
import { NamedIdentity } from "../components/NamedIdentity.js";
import { MoveIntent }  from "../components/Intents/MoveIntent.js";
import { AggroState, AGGRO_LEVELS } from "../components/AggroState.js";
import { getMonster }  from "../data/monsters.js";
import { forEachInRadius } from "../utils/spatialIndex.js";
import { canActThisTurn } from "../utils/speedGate.js";
import { CARDINAL_DIRS } from "../utils/directions.js";
import { isWalkable } from "../environment/dungeon/tileMap.js";
import { getTile } from "../environment/dungeon/tileMap.js";
import { TILE_STAIR_DOWN, TILE_STAIR_UP } from "../environment/dungeon/constants.js";
import { playerEntity } from "../utils/queries.js";

// Keep AI work bounded: only process enemies near the player.
const SCURRY_RADIUS = 20;

/**
 * Returns true if a tile is a suitable patrol destination (walkable and not a staircase).
 * Closed doors (walkable tile, solid entity) are allowed — the bump resolver will open them.
 */
function isPatrolStep(x, y) {
  if (!isWalkable(x, y)) return false;
  const t = getTile(x, y);
  return t !== TILE_STAIR_DOWN && t !== TILE_STAIR_UP;
}

/** @param {import('../../lib/ecs-js/index.js').World} world */
export function aiScurrySystem(world) {
  // Need the player position as the radius anchor.
  const player = playerEntity(world);
  if (!player) return;
  const playerPos = player.pos;

  forEachInRadius(world, playerPos.x, playerPos.y, SCURRY_RADIUS, (id, pos) => {
    const fac = world.get(id, Faction);
    if (!fac || fac.key !== "enemy") return;

    // Only idle creatures move here.
    const aggro = world.get(id, AggroState);
    if (!aggro || aggro.alertLevel !== AGGRO_LEVELS.unaware) return;

    const ni  = world.get(id, NamedIdentity);
    const def = ni ? getMonster(String(ni.identity || "")) : null;
    if (!def) return;

    // Speed gate: matches the cadence logic in aiChaseSystem.
    if (!canActThisTurn(world, id)) return;

    // Skip if another system already queued a move this tick.
    if (world.has(id, MoveIntent)) return;

    const intel = def.intelligence ?? 10;

    if (intel <= 3) {
      // ── Low intelligence: random scurry ────────────────────────────
      // 50 % chance to rest; creatures don't scurry every single turn.
      if (world.rand() < 0.5) return;

      const dir = CARDINAL_DIRS[Math.floor(world.rand() * CARDINAL_DIRS.length)];
      try { world.add(id, MoveIntent, { dx: dir.dx, dy: dir.dy }); } catch {}
    } else {
      // ── Higher intelligence: directed patrol ────────────────────────
      // 25 % chance to pause; patrols are more deliberate than a scurry.
      if (world.rand() < 0.25) return;

      let pdx = aggro.patrolDx | 0;
      let pdy = aggro.patrolDy | 0;

      // Assign an initial patrol direction if none set yet.
      if (pdx === 0 && pdy === 0) {
        const dir = CARDINAL_DIRS[Math.floor(world.rand() * CARDINAL_DIRS.length)];
        pdx = dir.dx;
        pdy = dir.dy;
      }

      // If the next tile in patrol direction is a wall or stair, pick a new heading.
      if (!isPatrolStep((pos.x | 0) + pdx, (pos.y | 0) + pdy)) {
        // Try directions excluding the current one (and its reverse to avoid immediately
        // bouncing back, if alternatives exist).
        const alts = CARDINAL_DIRS.filter(d => !(d.dx === pdx && d.dy === pdy));
        let picked = false;
        // Shuffle by consuming two rand() calls so ordering varies each turn.
        const offset = Math.floor(world.rand() * alts.length);
        for (let i = 0; i < alts.length; i++) {
          const d = alts[(offset + i) % alts.length];
          if (isPatrolStep((pos.x | 0) + d.dx, (pos.y | 0) + d.dy)) {
            pdx = d.dx;
            pdy = d.dy;
            picked = true;
            break;
          }
        }
        if (!picked) return; // fully cornered — stay put
      }

      aggro.patrolDx = pdx;
      aggro.patrolDy = pdy;
      try { world.add(id, MoveIntent, { dx: pdx, dy: pdy }); } catch {}
    }
  });
}
// src/rules/systems/aiFarmAnimalSystem.js
// Simple wandering AI for passive farm animals on the overworld (depth 0).
// Animals randomly scurry with a high rest chance, staying near their spawn.

import { Faction } from "../components/Faction.js";
import { CreatureType, CREATURE_TYPES } from "../components/CreatureType.js";
import { MoveIntent } from "../components/Intents/MoveIntent.js";
import { DungeonState } from "../components/DungeonState.js";
import { NamedIdentity } from "../components/NamedIdentity.js";
import { canActThisTurn } from "../utils/speedGate.js";
import { CARDINAL_DIRS } from "../utils/directions.js";
import { isWalkable } from "../environment/dungeon/tileMap.js";
import { playerEntity } from "../utils/queries.js";
import { forEachInRadius } from "../utils/spatialIndex.js";
import { getMonster } from "../data/monsters.js";
import { resolveSleepScheduleNow } from "../data/sleepProfiles.js";
import { isAsleep } from "../utils/sleep.js";

const ACTIVE_RADIUS = 8;
const VOCALIZATION_COOLDOWN = 200; // turns between vocalizations per chicken

/** Track vocalization cooldown per entity (Map<id, turnsLeft>) */
const _vocalizationCooldowns = new Map();

/** @param {import('../../lib/ecs-js/index.js').World} world */
export function aiFarmAnimalSystem(world) {
  // Only run on the overworld.
  let depth = -1;
  for (const [, ds] of world.query(DungeonState)) {
    depth = ds.currentDepth ?? -1;
    break;
  }
  if (depth !== 0) return;

  const player = playerEntity(world);
  if (!player) return;
  const pp = player.pos;

  forEachInRadius(world, pp.x, pp.y, ACTIVE_RADIUS, (id, pos) => {
    const fac = world.get(id, Faction);
    if (!fac || fac.key !== "neutral") return;

    const ct = world.get(id, CreatureType);
    if (!ct || ct.type !== CREATURE_TYPES.beast) return;

    const identity = String(world.get(id, NamedIdentity)?.identity || "");
    const def = getMonster(identity);
    if (def?._contentAiHints?.farmAnimal !== true) return;
    if (resolveSleepScheduleNow(def.sleep, world.step || 0) === true) return;
    if (isAsleep(world, id)) return;

    if (!canActThisTurn(world, id)) return;
    if (world.has(id, MoveIntent)) return;

    // Decrement vocalization cooldown
    const cooldown = _vocalizationCooldowns.get(id) ?? 0;
    if (cooldown > 0) {
      _vocalizationCooldowns.set(id, cooldown - 1);
    }

    // 5% chance to vocalize (if not on cooldown) — chickens cluck/cheep occasionally
    if (cooldown === 0 && world.rand() < 0.05) {
      if (identity) {
        world.emit?.('creature:vocalize', {
          id,
          identity,
          at: { x: pos.x | 0, y: pos.y | 0 },
        });
        _vocalizationCooldowns.set(id, VOCALIZATION_COOLDOWN);
      }
    }

    // 70% chance to rest — chickens mostly peck in place.
    if (world.rand() < 0.7) return;

    const dir = CARDINAL_DIRS[Math.floor(world.rand() * CARDINAL_DIRS.length)];
    const nx = (pos.x | 0) + dir.dx;
    const ny = (pos.y | 0) + dir.dy;
    if (!isWalkable(nx, ny)) return;

    try { world.add(id, MoveIntent, { dx: dir.dx, dy: dir.dy }); } catch {}
  });
}
// src/rules/systems/aiPolicySystem.js
// Neural-network policy override for high-intelligence monsters (intel ≥ 7).
//
// Runs AFTER aiChaseSystem in the 'ai' phase.
//
// Contract:
//   • If the entity already has CastSpellIntent (set by a whileLOS hook), skip it —
//     the hook made a contextual decision and we don't want to second-guess it here.
//   • Otherwise: extract features → forward pass → argmax → applyAction.
//     applyAction can replace MoveIntent with a better direction, add CastSpellIntent,
//     or remove MoveIntent (wait/hold).
//   • Falls back silently if no trained weights exist for this tier (TRAINED_WEIGHTS empty).

import { Faction }       from '../components/Faction.js';
import { Brain }         from '../components/Brain.js';
import { AggroState, AGGRO_LEVELS } from '../components/AggroState.js';
import { NamedIdentity } from '../components/NamedIdentity.js';
import { CastSpellIntent } from '../components/Intents/CastSpellIntent.js';
import { forEachInRadius } from '../utils/spatialIndex.js';
import { playerEntity }    from '../utils/queries.js';
import { canActThisTurn }  from '../utils/speedGate.js';
import { hasLOS }          from '../../shared/math/gridLOS.js';
import { buildBlocksVisionMap, blockedCallback } from '../utils/vision.js';
import { chebyshevScalar } from '../utils/distance.js';
import { getMonster }      from '../data/monsters.js';
import { extractFeatures } from '../ai/policyFeatures.js';
import { forward, argmax, deserializeNet } from '../ai/tinyMLP.js';
import { applyAction }     from '../ai/policyAction.js';
import { getWeightsForIntelligence } from '../data/aiWeights.js';

const POLICY_INTEL_THRESHOLD = 7;
const ACTIVE_RADIUS          = 32;

// Cache deserialised networks keyed by tier string (lives for the page lifetime).
/** @type {Map<string, ReturnType<import('../ai/tinyMLP.js').createMLP>>} */
const NET_CACHE = new Map();

/**
 * @param {number} intel
 * @returns {ReturnType<import('../ai/tinyMLP.js').createMLP> | null}
 */
function getNet(intel) {
  const tier = intel >= 9 ? 'caster' : 'tactical';
  if (NET_CACHE.has(tier)) return NET_CACHE.get(tier);

  const spec = getWeightsForIntelligence(intel);
  if (!spec) return null; // untrained — policy inactive for this tier

  const net = deserializeNet(spec);
  NET_CACHE.set(tier, net);
  return net;
}

/** @param {any} world */
export function aiPolicySystem(world) {
  const _player = playerEntity(world);
  if (!_player) return;

  const playerId  = _player.id;
  const playerPos = _player.pos;

  // LOS blocking map — built once per tick, shared.
  let _isBlocked = null;
  function ensureBlocked() {
    if (!_isBlocked) _isBlocked = blockedCallback(buildBlocksVisionMap(world));
    return _isBlocked;
  }

  forEachInRadius(world, playerPos.x, playerPos.y, ACTIVE_RADIUS, (id, pos) => {
    // Only enemy entities
    const fac = world.get(id, Faction);
    if (!fac || fac.key !== 'enemy') return;

    // Intelligence gate
    const brain = world.get(id, Brain);
    const intel = Number(brain?.intelligence ?? 10);
    if (intel < POLICY_INTEL_THRESHOLD) return;

    // Only act when hunting and it's this monster's turn
    const aggro = world.get(id, AggroState);
    if (!aggro || aggro.alertLevel !== AGGRO_LEVELS.hunting) return;
    if (!canActThisTurn(world, id)) return;

    // If a whileLOS hook already cast a spell this tick, don't interfere
    if (world.has(id, CastSpellIntent)) return;

    // Network must be trained for this tier
    const net = getNet(intel);
    if (!net) return;

    // LOS check (monsters without LOS are handled by aiChaseSystem's search)
    const dist = chebyshevScalar(pos.x | 0, pos.y | 0, playerPos.x | 0, playerPos.y | 0);
    if (dist > (brain?.visionRange ?? 8)) return;
    const canSee = hasLOS(
      pos.x | 0, pos.y | 0,
      playerPos.x | 0, playerPos.y | 0,
      ensureBlocked(),
    );
    if (!canSee) return;

    // Extract features and run policy
    const features = extractFeatures(world, id, pos, playerId, playerPos);
    const probs    = forward(net, features);
    const action   = argmax(probs);

    const learnedSpells = Array.isArray(brain?.learnedSpellIds) ? brain.learnedSpellIds : [];
    applyAction(world, id, playerId, action, learnedSpells);
  });
}

